export function useAuraThemeColors() {
  const { setTheme, theme, resolvedTheme } = useTheme();
  const [mounted, setMounted] = useState(false);
  const themeColors = useSyncExternalStore(
    subscribe,
    getSnapshot,
    getServerSnapshot
  );

  useLayoutEffect(() => {
    setMounted(true);
  }, []);

  useLayoutEffect(() => {
    const mode = consumePaintAppearance(
      mounted && (resolvedTheme === "light" || resolvedTheme === "dark")
        ? resolvedTheme
        : undefined
    );
    if (!mode) return;
    injectThemeColors(mode, getSnapshot()[mode]);
  }, [mounted, resolvedTheme, themeColors]);

  const domAppearance: "light" | "dark" | null =
    mounted && typeof document !== "undefined"
      ? document.documentElement.classList.contains("dark")
        ? "dark"
        : document.documentElement.classList.contains("light")
          ? "light"
          : null
      : null;
  const appearance: "light" | "dark" =
    resolvedTheme === "dark" || resolvedTheme === "light"
      ? resolvedTheme
      : domAppearance === "dark"
        ? "dark"
        : "light";
  const currentColors = themeColors[appearance];

  const setColor = useCallback(
    (field: keyof ThemeColors, value: string) => {
      if (!isValidHex(value)) return;
      const current = getSnapshot();
      const normalized = normalizeHex(value);
      const nextMode: ThemeColors = {
        ...current[appearance],
        [field]: normalized,
      };
      if (field === "gray") {
        nextMode.background = canvasFromGray(normalized, appearance);
      }
      writeToStorage({
        ...current,
        [appearance]: nextMode,
      });
    },
    [appearance]
  );

  const applyScheme = useCallback((scheme: ThemeColorsByMode) => {
    if (!isValidThemeColorsByMode(scheme)) return;
    writeToStorage({
      light: toNormalizedThemeColors(scheme.light),
      dark: toNormalizedThemeColors(scheme.dark),
    });
  }, []);

  const applyPreset = useCallback(
    (preset: ThemePreset) => {
      const scheme = resolvePreset(preset);
      if (!isValidThemeColorsByMode(scheme)) return;
      const normalized: ThemeColorsByMode = {
        light: toNormalizedThemeColors(scheme.light),
        dark: toNormalizedThemeColors(scheme.dark),
      };
      writeToStorage(normalized);
      injectThemeColors(appearance, normalized[appearance]);
    },
    [appearance]
  );

  const resetDefaults = useCallback(() => {
    writeToStorage(DEFAULT_THEME_COLORS);
  }, []);

  const downloadCSS = useCallback(() => {
    const cssContent = generateGlobalsCssContent(themeColors);
    const blob = new Blob([cssContent], { type: "text/css" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "globals.css";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }, [themeColors]);

  return {
    mounted,
    appearance,
    theme,
    resolvedTheme,
    themeColors,
    currentColors,
    setTheme,
    setColor,
    applyScheme,
    applyPreset,
    resetDefaults,
    downloadCSS,
  };
}

import { canvasFromGray } from "@/utils/scheme-from-seed";

export type ThemePresetMode = {
  accent: string;
  gray: string;
  background?: string;
};

export type ThemePreset = {
  id: string;
  name: string;
  light: ThemePresetMode;
  dark: ThemePresetMode;
};

export type ResolvedThemeColors = {
  accent: string;
  gray: string;
  background: string;
};

function pairedPreset(
  id: string,
  name: string,
  accent: string,
  gray: string,
): ThemePreset {
  return {
    id,
    name,
    light: { accent, gray },
    dark: { accent, gray },
  };
}

